    static int predict(const double* features) {
        double scaled_features[NUM_FEATURES];
        for (int i = 0; i < NUM_FEATURES; i++) {
            scaled_features[i] = (features[i] - SCALER_MEAN[i]) / SCALER_STD[i];
        }

        int votes[NUM_CLASSES] = {0};
        for (int t = 0; t < NUM_TREES; t++) {
            int class_idx = predict_tree_class_index(scaled_features, t);
            if (class_idx >= 0 && class_idx < NUM_CLASSES) {
                votes[class_idx] += 1;
            }
        }

        int best_class_idx = 0;
        for (int c = 1; c < NUM_CLASSES; c++) {
            if (votes[c] > votes[best_class_idx]) {
                best_class_idx = c;
            }
        }

        return CLASSES[best_class_idx];
    }

    static int predict_proba(const double* features, double* probabilities) {
        double scaled_features[NUM_FEATURES];
        for (int i = 0; i < NUM_FEATURES; i++) {
            scaled_features[i] = (features[i] - SCALER_MEAN[i]) / SCALER_STD[i];
        }

        int votes[NUM_CLASSES] = {0};
        for (int t = 0; t < NUM_TREES; t++) {
            int class_idx = predict_tree_class_index(scaled_features, t);
            if (class_idx >= 0 && class_idx < NUM_CLASSES) {
                votes[class_idx] += 1;
            }
        }

        int best_class_idx = 0;
        for (int c = 0; c < NUM_CLASSES; c++) {
            probabilities[c] = static_cast<double>(votes[c]) / static_cast<double>(NUM_TREES);
            if (probabilities[c] > probabilities[best_class_idx]) {
                best_class_idx = c;
            }
        }

        return CLASSES[best_class_idx];
    }

